+void triton::setOpLoopDepth(mlir::Operation *op) {
+  static constexpr int kIntegerBitWidth = 32;
+  int loopDepth = 1;
+  for (mlir::Operation *parent = op->getParentOp(); parent;
+       parent = parent->getParentOp()) {
+    if (isa<scf::ForOp, scf::WhileOp>(parent)) {
+      ++loopDepth;
+    }
