+
+std::unique_ptr<mlir::Pass>
+mlir::triton::proton::createLowerAscendProtonToHIVMPass(
+    int32_t dataSegmentBytes) {
+  auto pass = std::make_unique<LowerAscendProtonToHIVMPass>();
+  pass->dataSegmentBytes = dataSegmentBytes;
+  return pass;
+}
